<section data-butchery-panel="outgoing" <?=$section!=='outgoing'?'hidden':''?> class="form-panel butchery-slaughter-actions"><div class="butchery-slaughter-toolbar"><h3>Sorties</h3><?php ob_start(); ?><form data-butchery-form data-outgoing-form data-confirm="Confirmer cette opération ?" method="post" action="<?=e(base_url('butchery/sales'))?>"><?=csrf_field()?><input type="hidden" name="_section" value="<?=e($section)?>"><div class="feed-form-body"><p data-feed-error class="app-alert app-alert-error" role="alert" hidden></p><div class="form-grid"><label><span>Type de stock *</span><select name="lot_type" required><option value="raw">Matière sans transformation</option><option value="finished">Produit fini</option></select></label><label><span>Lot à vendre *</span><select name="lot_id" required><option value="">Choisir un lot</option><?php foreach(['raw'=>$raw,'finished'=>$finished] as $lotType=>$lots):foreach($lots as $lot):if($lot['status']!=='available'||$lot['expiry_date']<date('Y-m-d')||(float)$lot['quantity_kg']-(float)$lot['reserved_kg']<=0)continue;?><option data-outgoing-lot="<?=e(json_encode(['lot'=>$lot['lot_number'],'item'=>$lot['item_name'],'available'=>max(0,(float)$lot['quantity_kg']-(float)$lot['reserved_kg']),'expiry'=>date('d/m/Y',strtotime($lot['expiry_date']))],JSON_UNESCAPED_UNICODE))?>" data-lot-type="<?=e($lotType)?>" value="<?=e($lot['id'])?>"><?=e($lot['lot_number'].' · '.$lot['item_name'].' · '.$lot['quantity_kg'].' kg · DLC '.$lot['expiry_date'])?></option><?php endforeach;endforeach;?></select></label><div class="butchery-plan-recipe" data-outgoing-summary aria-live="polite" hidden></div><label><span>Quantité (kg) *</span><input type="number" step="0.001" name="quantity_kg" placeholder="kg" required min="0.001"></label><label><span>Client *</span><input name="customer_name" placeholder="Client" required></label><label><span>Prix unitaire / kg</span><input type="number" step="0.01" name="unit_price" placeholder="Prix" min="0"></label></div><p class="butchery-plan-recipe" data-outgoing-balance aria-live="polite" hidden></p></div><footer><button type="button" class="btn-secondary" data-workspace-modal-close>Annuler</button><button type="submit" class="btn-primary">Vendre</button></footer></form><?php $butcheryDrawer('Enregistrer une vente',ob_get_clean(),'create','Nouvelle vente'); ?><?php ob_start(); ?><form data-butchery-form data-outgoing-form data-confirm="Confirmer cette opération ?" method="post" action="<?=e(base_url('butchery/transfers'))?>"><?=csrf_field()?><input type="hidden" name="_section" value="<?=e($section)?>"><div class="feed-form-body"><p data-feed-error class="app-alert app-alert-error" role="alert" hidden></p><div class="form-grid"><label><span>Lot à transférer *</span><select name="finished_lot_id" required><?php foreach($finished as$x):if($x['status']==='available'&&$x['expiry_date']>=date('Y-m-d')&&(float)$x['quantity_kg']>(float)$x['reserved_kg']):?><option data-outgoing-lot="<?=e(json_encode(['lot'=>$x['lot_number'],'item'=>$x['item_name'],'available'=>max(0,(float)$x['quantity_kg']-(float)$x['reserved_kg']),'expiry'=>date('d/m/Y',strtotime($x['expiry_date']))],JSON_UNESCAPED_UNICODE))?>" value="<?=$x['id']?>"><?=e($x['lot_number'].' — '.$x['quantity_kg'].' kg')?></option><?php endif;endforeach;?></select></label><div class="butchery-plan-recipe" data-outgoing-summary aria-live="polite" hidden></div><label><span>Quantité (kg) *</span><input name="quantity_kg" type="number" step="0.001" placeholder="kg" required min="0.001"></label></div><p class="butchery-plan-recipe" data-outgoing-balance aria-live="polite" hidden></p></div><footer><button type="button" class="btn-secondary" data-workspace-modal-close>Annuler</button><button type="submit" class="btn-primary">Nouveau transfert vers DECO</button></footer></form><?php $butcheryDrawer('Nouveau transfert vers DECO',ob_get_clean(),'create','Nouveau transfert'); ?></div></section>
<?php if($section==='outgoing') require __DIR__.'/outgoing_history.php'; ?>
